    <title>Terms of Use Consent</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f3f6fb;
        --surface: #ffffff;
        --surface-2: #f8fafc;
        --text: #0f172a;
        --muted: #475569;
        --border: #cbd5e1;
        --accent: #2563eb;
        --accent-strong: #1d4ed8;
        --focus: #0f766e;
        --shadow: 0 24px 60px rgba(15, 23, 42, 0.12);
      }

      * {
        box-sizing: border-box;
      }

      html {
        min-height: 100%;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top, #e2e8f0 0%, transparent 42%),
          linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
        line-height: 1.5;
      }

      a {
        color: inherit;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        padding: 0.75rem 1rem;
        border-radius: 0.75rem;
        background: var(--surface);
        color: var(--text);
        border: 1px solid var(--border);
        transform: translateY(-200%);
        transition: transform 0.2s ease;
      }

      .skip-link:focus {
        transform: translateY(0);
        outline: 3px solid var(--focus);
        outline-offset: 2px;
      }

      main {
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 5rem 1.25rem 2rem;
      }

      .card {
        width: min(100%, 28rem);
        padding: 2rem;
        border: 1px solid rgba(203, 213, 225, 0.85);
        border-radius: 1.5rem;
        background: rgba(255, 255, 255, 0.88);
        box-shadow: var(--shadow);
        backdrop-filter: blur(14px);
      }

      .eyebrow {
        margin: 0 0 0.5rem;
        font-size: 0.875rem;
        font-weight: 600;
        color: var(--accent-strong);
        letter-spacing: 0.02em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(1.75rem, 4vw, 2.25rem);
        line-height: 1.15;
        letter-spacing: -0.03em;
      }

      .lead {
        margin: 0.75rem 0 1.75rem;
        color: var(--muted);
      }

      form {
        display: grid;
        gap: 1.25rem;
      }

      fieldset {
        margin: 0;
        padding: 0;
        border: 0;
      }

      .form-field {
        display: grid;
        gap: 0.5rem;
        padding: 1rem;
        border: 1px solid var(--border);
        border-radius: 1rem;
        background: var(--surface-2);
      }

      .checkbox-label {
        display: inline-flex;
        align-items: flex-start;
        gap: 0.75rem;
        font-weight: 600;
        color: var(--text);
        cursor: pointer;
      }

      .checkbox-label input {
        inline-size: 1.125rem;
        block-size: 1.125rem;
        margin-top: 0.15rem;
        accent-color: var(--accent);
        flex: 0 0 auto;
      }

      .checkbox-label input:focus-visible,
      button:focus-visible {
        outline: 3px solid var(--focus);
        outline-offset: 3px;
      }

      .helper-text {
        margin: 0;
        color: var(--muted);
        font-size: 0.9375rem;
        padding-left: 1.875rem;
      }

      .actions {
        display: flex;
        justify-content: flex-end;
      }

      button {
        appearance: none;
        border: 0;
        border-radius: 999px;
        padding: 0.875rem 1.25rem;
        font: inherit;
        font-weight: 700;
        color: #fff;
        background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
        box-shadow: 0 10px 20px rgba(37, 99, 235, 0.24);
        cursor: pointer;
      }

      button:hover {
        filter: brightness(1.03);
      }

      button:active {
        transform: translateY(1px);
      }

      .status {
        min-height: 1.5rem;
        margin: 0;
        font-size: 0.9375rem;
        color: var(--accent-strong);
      }

      .sr-only {
        position: absolute;
        width: 1px;
        height: 1px;
        padding: 0;
        margin: -1px;
        overflow: hidden;
        clip: rect(0, 0, 0, 0);
        white-space: nowrap;
        border: 0;
      }

      @media (max-width: 420px) {
        .card {
          padding: 1.5rem;
          border-radius: 1.25rem;
        }

        .actions {
          justify-content: stretch;
        }

        button {
          width: 100%;
        }
      }

      @media (forced-colors: active) {
        :root {
          --bg: Canvas;
          --surface: Canvas;
          --surface-2: Canvas;
          --text: CanvasText;
          --muted: CanvasText;
          --border: ButtonBorder;
          --accent: ButtonText;
          --accent-strong: ButtonText;
          --focus: Highlight;
        }

        .card,
        .form-field,
        .skip-link,
        button {
          forced-color-adjust: auto;
          box-shadow: none;
        }

        button {
          border: 1px solid ButtonBorder;
          color: ButtonText;
          background: ButtonFace;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="app"></div>

    <script>
      const components = {
        App() {
          return `
            <main id="main-content">
              <section class="card" aria-labelledby="page-title">
                <p class="eyebrow">Account access</p>
                <h1 id="page-title">Agree to continue</h1>
                <p class="lead">Please confirm that you accept the terms before submitting.</p>

                <form id="consent-form" novalidate>
                  <fieldset>
                    <legend class="sr-only">Terms of use consent</legend>
                    <div class="form-field">
                      <label class="checkbox-label" for="terms">
                        <input id="terms" name="terms" type="checkbox" required aria-describedby="terms-help" />
                        <span>I agree to the Terms of Use <span aria-hidden="true">*</span></span>
                      </label>
                      <p id="terms-help" class="helper-text">Required to submit the form.</p>
                    </div>
                  </fieldset>

                  <div class="actions">
                    <button type="submit">Submit</button>
                  </div>
                  <p id="status" class="status" aria-live="polite"></p>
                </form>
              </section>
            </main>
          `;
        }
      };

      document.getElementById("app").innerHTML = components.App();

      const form = document.getElementById("consent-form");
      const checkbox = document.getElementById("terms");
      const status = document.getElementById("status");

      form.addEventListener("submit", (event) => {
        if (!form.checkValidity()) {
          return;
        }

        event.preventDefault();
        status.textContent = checkbox.checked ? "Consent recorded." : "";
      });
    </script>
  </body>
</html>
