       const components = {
         App() {
           return `
             <main id="main-content">
               <section class="card" aria-labelledby="page-title">
                 <p class="eyebrow">Account access</p>
                 <h1 id="page-title">Agree to continue</h1>
                 <p class="lead">Please confirm that you accept the terms before submitting.</p>

                 <form id="consent-form">
                   <fieldset>
                     <legend class="sr-only">Terms of use consent</legend>
                     <div class="form-field">
                       <label class="checkbox-label" for="terms">
                         <input id="terms" name="terms" type="checkbox" required aria-describedby="terms-help" />
                         <span>I agree to the Terms of Use <span aria-hidden="true">*</span></span>
                       </label>
                       <p id="terms-help" class="helper-text">Required to submit the form.</p>
                     </div>
                   </fieldset>

                   <div class="actions">
                     <button type="submit">Submit</button>
                   </div>
                   <p id="status" class="status" aria-live="polite"></p>
                 </form>
               </section>
             </main>
           `;
         }
       };

       document.getElementById("app").innerHTML = components.App();

       const form = document.getElementById("consent-form");
       const checkbox = document.getElementById("terms");
       const status = document.getElementById("status");

       form.addEventListener("submit", (event) => {
         if (!form.reportValidity()) {
           return;
         }

         event.preventDefault();
         status.textContent = checkbox.checked ? "Consent recorded." : "";
       });
     </script>
   </body>
 </html>

')
